# Purpose: Keep experiment-report transformations and plot delivery out of the Rmd.
# Input: RDS result objects generated by 02-ablation-experiment.R.
# Parameters: Display k and technical columns selected by the Rmd.
# Output: Tidy tables for figures and evidence-anchored prose.

.ae_ablation_params <- function(filtered_cohorts, n_cores) {
  list(
    comparison = list(
      module_ids = NULL,
      direct_group = "Direct-GSClassifier",
      cohort_group = "Cohort-d1"
    ),
    provenance = list(
      external_cohorts = filtered_cohorts,
      max_reference_samples = Inf,
      max_query_samples = Inf,
      require_external = TRUE
    ),
    anchors = list(
      primary = "cancer_type",
      primary_role = "independent",
      bank_aligned = "tissue",
      technical = c("assay_type", "platform_id", "source_system"),
      min_reference_cohorts = 2L
    ),
    geometry = list(
      k = c(5L, 15L, 30L),
      search = "annoy",
      n_trees = 75L,
      search_k = 10000L,
      exact_validation_queries = 30L,
      min_annoy_recall = 0.90,
      geometry_samples = 5000L,
      distance_pairs = 100000L
    ),
    validation = list(
      enabled = TRUE,
      learning_fractions = c(0.10, 0.25, 0.50, 1.00),
      repeats = 3L,
      inner_folds = 3L,
      lambda = c(0.1, 1, 10),
      nrounds = 30L,
      min_class_n = 20L,
      numCores = n_cores
    ),
    scaling = list(
      enabled = TRUE,
      module_counts = c(10L, 25L, 50L, 75L, 100L, 125L, 150L),
      sequences = 5L,
      direct_feature_type = "all",
      sensitivity_feature_type = "gene_pair",
      biology_anchors = character(),
      score_reference_samples = 5000L,
      score_query_samples = 2000L,
      lambda = 1,
      bootstrap = 2000L
    ),
    controls = list(
      null_rp = TRUE,
      null_rp_rank = 100L,
      null_rp_seeds = 20260805L + seq_len(3L),
      null_perm = TRUE
    ),
    tradeoffs = list(
      decoder = TRUE,
      decoder_rank = 50L,
      decoder_lambda = 1,
      decoder_max_reference_samples = 10000L,
      decoder_max_query_samples = 5000L
    ),
    output = list(
      cover = TRUE,
      cache_external_d1 = TRUE
    )
  )
}

.ae_metric_long <- function(data, id_columns, metric_columns) {
  parts <- lapply(metric_columns, function(metric) {
    result <- data[, id_columns, drop = FALSE]
    result$metric <- metric
    result$value <- data[[metric]]
    result
  })
  do.call(rbind, parts)
}

.ae_retrieval_cohort_delta <- function(retrieval, k) {
  data <- retrieval$paired[retrieval$paired$k == k, , drop = FALSE]
  .ae_metric_long(
    data,
    id_columns = c("sample_id", "cohort", "label", "k"),
    metric_columns = c(
      "delta_top_k_label_rate",
      "delta_mrr",
      "delta_top1_label_match"
    )
  ) |>
    dplyr::group_by(.data$cohort, .data$metric) |>
    dplyr::summarise(
      estimate = mean(.data$value, na.rm = TRUE),
      sample_count = dplyr::n(),
      .groups = "drop"
    )
}

.ae_technical_delta <- function(retrieval, k, technical_columns) {
  data <- retrieval$per_sample[
    retrieval$per_sample$k == k,
    ,
    drop = FALSE
  ]
  keys <- c("sample_id", "cohort", "label", "k")
  direct <- data[data$representation == "Direct-GSClassifier", , drop = FALSE]
  d1 <- data[data$representation == "Cohort-d1", , drop = FALSE]
  paired <- merge(d1, direct, by = keys, suffixes = c("_d1", "_direct"))
  parts <- lapply(technical_columns, function(column) {
    metric <- paste0(column, "_match_excess")
    d1_name <- paste0(metric, "_d1")
    direct_name <- paste0(metric, "_direct")
    if (!all(c(d1_name, direct_name) %in% colnames(paired))) {
      return(NULL)
    }
    data.frame(
      sample_id = paired$sample_id,
      cohort = paired$cohort,
      technical_factor = column,
      delta_excess = paired[[d1_name]] - paired[[direct_name]],
      stringsAsFactors = FALSE
    )
  })
  parts <- parts[!vapply(parts, is.null, logical(1))]
  data <- do.call(rbind, parts)
  data |>
    dplyr::group_by(.data$cohort, .data$technical_factor) |>
    dplyr::summarise(
      estimate = mean(.data$delta_excess, na.rm = TRUE),
      sample_count = dplyr::n(),
      .groups = "drop"
    )
}

.ae_learning_summary <- function(curve) {
  curve$metrics |>
    dplyr::group_by(.data$representation, .data$requested_fraction) |>
    dplyr::summarise(
      estimate = mean(.data$balanced_accuracy, na.rm = TRUE),
      se = stats::sd(.data$balanced_accuracy, na.rm = TRUE) /
        sqrt(sum(is.finite(.data$balanced_accuracy))),
      min = min(.data$balanced_accuracy, na.rm = TRUE),
      max = max(.data$balanced_accuracy, na.rm = TRUE),
      .groups = "drop"
    )
}

.ae_top_abs <- function(data, value, n = 3L) {
  data[order(abs(data[[value]]), decreasing = TRUE), , drop = FALSE] |>
    utils::head(n)
}

.ae_resolve_module_labels <- function(module_ids, resolution_audit) {
  bank_tissue <- sub("[|].*$", "", module_ids)
  cohort <- sub("^[^|]*[|]", "", module_ids)
  mapped_tissue <- resolution_audit$resolved_tissue[
    match(cohort, resolution_audit$cohort)
  ]
  display_tissue <- ifelse(
    bank_tissue == "Undefined" & !is.na(mapped_tissue),
    mapped_tissue,
    bank_tissue
  )
  paste(display_tissue, cohort, sep = "|")
}

.ae_find_source_line <- function(path, pattern) {
  lines <- readLines(path, warn = FALSE)
  match(TRUE, grepl(pattern, lines, fixed = TRUE))
}

.ae_save_plot <- function(plot, file_stem, figure_dir, preview_dir, figure_params, dpi) {
  pdf_path <- file.path(figure_dir, paste0(file_stem, ".pdf"))
  jpg_path <- file.path(preview_dir, paste0(file_stem, ".jpg"))
  ggplot2::ggsave(
    filename = pdf_path,
    plot = plot,
    width = figure_params$width_in,
    height = figure_params$height_in,
    device = grDevices::cairo_pdf
  )
  bensz_pdf_to_jpg(pdf_path, jpg_path, dpi = dpi)
}
